import heapq
from itertools import count

def min_cost_route(n, edges, s, t, switch_cost):
    if s == t:
        return 0
    adj = [[] for _ in range(n)]
    for u, v, w, col in edges:
        adj[u].append((v, w, col))
        adj[v].append((u, w, col))
    INF = float("inf")
    dist = {}
    tie = count()
    pq = [(0, next(tie), s, None)]
    while pq:
        d, _, u, col = heapq.heappop(pq)
        if u == t:
            return d
        if d > dist.get((u, col), INF):
            continue
        for v, w, col2 in adj[u]:
            nd = d + w
            if col is not None and col2 != col:
                nd += switch_cost
            key = (v, col2)
            if nd < dist.get(key, INF):
                dist[key] = nd
                heapq.heappush(pq, (nd, next(tie), v, col2))
    return -1

def _linear_exact(arr, k):
    NEG = float("-inf")
    m = len(arr)
    dp = [[NEG] * (k + 1) for _ in range(m + 1)]
    for i in range(m + 1):
        dp[i][0] = 0
    for i in range(1, m + 1):
        for j in range(1, k + 1):
            skip = dp[i - 1][j]
            if i >= 2:
                take = dp[i - 2][j - 1] + arr[i - 1]
            else:
                take = arr[0] if j == 1 else NEG
            dp[i][j] = skip if skip >= take else take
    return dp[m][k]


def best_circular_selection(values, k):
    n = len(values)
    if k == 0:
        return 0
    if k < 0:
        raise ValueError("impossible")
    if n == 1:
        if k == 1:
            return values[0]
        raise ValueError("impossible")
    best = max(_linear_exact(values[1:], k), _linear_exact(values[:-1], k))
    if best == float("-inf"):
        raise ValueError("impossible")
    return best

from collections import deque

def min_steps(grid, c):
    R = len(grid)
    C = len(grid[0])
    if grid[0][0] == -1 or grid[R - 1][C - 1] == -1:
        return -1
    INF = float("inf")

    def bfs(sr, sc):
        d = [[INF] * C for _ in range(R)]
        d[sr][sc] = 0
        dq = deque([(sr, sc)])
        while dq:
            r, col = dq.popleft()
            base = d[r][col] + 1
            for nr, nc in ((r + 1, col), (r - 1, col), (r, col + 1), (r, col - 1)):
                if 0 <= nr < R and 0 <= nc < C and grid[nr][nc] != -1 and d[nr][nc] == INF:
                    d[nr][nc] = base
                    dq.append((nr, nc))
        return d

    d1 = bfs(0, 0)
    d2 = bfs(R - 1, C - 1)
    best = d1[R - 1][C - 1]

    groups = {}
    for r in range(R):
        for col in range(C):
            v = grid[r][col]
            if v != -1:
                groups.setdefault(v, []).append((r, col))
    for cells in groups.values():
        if len(cells) < 2:
            continue
        m1 = min(d1[r][col] for r, col in cells)
        m2 = min(d2[r][col] for r, col in cells)
        if m1 < INF and m2 < INF:
            cand = m1 + c + m2
            if cand < best:
                best = cand
    return -1 if best == INF else best

def max_sessions(intervals, gap):
    count = 0
    last_end = None
    for s, e in sorted(intervals, key=lambda p: p[1]):
        if last_end is None or s >= last_end + gap:
            count += 1
            last_end = e
    return count

def smallest_balanced(s):
    n = len(s)
    if n % 2:
        raise ValueError("no balanced completion")
    need_open = n // 2 - s.count("(")
    if need_open < 0 or need_open > s.count("?"):
        raise ValueError("no balanced completion")
    out = []
    used = 0
    for ch in s:
        if ch == "?":
            if used < need_open:
                out.append("(")
                used += 1
            else:
                out.append(")")
        else:
            out.append(ch)
    bal = 0
    for ch in out:
        bal += 1 if ch == "(" else -1
        if bal < 0:
            raise ValueError("no balanced completion")
    if bal != 0:
        raise ValueError("no balanced completion")
    return "".join(out)

def longest_spaced_repeat(s, gap):
    n = len(s)
    if n == 0:
        return 0
    best = 0
    dp = [[0] * n for _ in range(n)]
    for j in range(1, n):
        for i in range(j):
            if s[i] == s[j]:
                cap = j - i - gap
                if cap <= 0:
                    continue
                run = dp[i - 1][j - 1] + 1 if i > 0 else 1
                v = run if run < cap else cap
                dp[i][j] = v
                if v > best:
                    best = v
    return best

def min_insertions(s, allowed):
    allowed = set(allowed)
    n = len(s)
    if n <= 1:
        return 0
    INF = float("inf")
    dp = [[0] * n for _ in range(n)]
    for length in range(2, n + 1):
        for i in range(0, n - length + 1):
            j = i + length - 1
            best = INF
            if s[i] == s[j]:
                inner = dp[i + 1][j - 1] if length > 2 else 0
                best = inner
            if s[j] in allowed and dp[i][j - 1] + 1 < best:
                best = dp[i][j - 1] + 1
            if s[i] in allowed and dp[i + 1][j] + 1 < best:
                best = dp[i + 1][j] + 1
            dp[i][j] = best
    return -1 if dp[0][n - 1] == INF else dp[0][n - 1]

def resolve_build_order(deps):
    graph = {}
    for pkg, ds in deps.items():
        graph.setdefault(pkg, [])
        for d in ds:
            graph.setdefault(d, [])
            graph[pkg].append(d)
    order = []
    done = set()
    visiting = set()

    def visit(node):
        if node in done:
            return
        if node in visiting:
            raise ValueError("dependency cycle detected at " + node)
        visiting.add(node)
        for dep in sorted(graph[node]):
            visit(dep)
        visiting.remove(node)
        done.add(node)
        order.append(node)

    for node in sorted(graph):
        visit(node)
    return order

import re

def compute_balances(transactions):
    balances = {}
    for tx in transactions:
        amount = tx["amount"]
        m = re.fullmatch(r"(\d+)(?:\.(\d{1,2}))?", amount)
        if m is None:
            raise ValueError("malformed amount: %r" % (amount,))
        whole, frac = m.group(1), m.group(2) or ""
        cents = int(whole) * 100 + int(frac.ljust(2, "0"))
        if cents <= 0:
            raise ValueError("amount must be positive")
        balances[tx["from"]] = balances.get(tx["from"], 0) - cents
        balances[tx["to"]] = balances.get(tx["to"], 0) + cents
    return balances

def apply_hunks(lines, hunks):
    ordered = sorted(hunks, key=lambda h: h[0])
    for i in range(1, len(ordered)):
        prev, cur = ordered[i - 1], ordered[i]
        if cur[0] == prev[0] or cur[0] < prev[0] + prev[1]:
            raise ValueError("conflicting hunks")
    for start, delete, _insert in ordered:
        if start < 0 or start + delete > len(lines):
            raise ValueError("hunk out of range")
    result = list(lines)
    for start, delete, insert in reversed(ordered):
        result[start:start + delete] = list(insert)
    return result

def merge_settings(defaults, overrides):
    result = dict(defaults)
    for key, value in overrides.items():
        if isinstance(value, dict) and isinstance(result.get(key), dict):
            result[key] = merge_settings(result[key], value)
        else:
            result[key] = value
    return result

def insert_booking(bookings, new):
    start, end = new
    if start >= end:
        raise ValueError("empty booking")
    result = []
    i = 0
    while i < len(bookings) and bookings[i][1] <= start:
        result.append(bookings[i])
        i += 1
    while i < len(bookings) and bookings[i][0] < end:
        start = min(start, bookings[i][0])
        end = max(end, bookings[i][1])
        i += 1
    result.append((start, end))
    result.extend(bookings[i:])
    return result

def purge_expired(sessions, now):
    purged = [sid for sid, expiry in sessions.items() if expiry <= now]
    for sid in purged:
        del sessions[sid]
    return purged

class RateLimiter:
    def __init__(self, max_calls, window_seconds):
        self.max_calls = max_calls
        self.window = window_seconds
        self.calls = []

    def allow(self, timestamp):
        self.calls = [t for t in self.calls if timestamp - t < self.window]
        if len(self.calls) < self.max_calls:
            self.calls.append(timestamp)
            return True
        return False

class CountingBag:
    def __init__(self):
        self._counts = {}
        self._entered = {}
        self._tick = 0

    def add(self, item):
        if item not in self._counts:
            self._tick += 1
            self._entered[item] = self._tick
            self._counts[item] = 0
        self._counts[item] += 1
        return self._counts[item]

    def discard(self, item):
        c = self._counts.get(item, 0)
        if c == 0:
            return False
        if c == 1:
            del self._counts[item]
            del self._entered[item]
        else:
            self._counts[item] = c - 1
        return True

    def count(self, item):
        return self._counts.get(item, 0)

    def __len__(self):
        return sum(self._counts.values())

    def distinct(self):
        return len(self._counts)

    def most_common(self, k):
        if k < 0:
            raise ValueError("k must be >= 0")
        ranked = sorted(self._counts.items(),
                        key=lambda kv: (-kv[1], self._entered[kv[0]]))
        return ranked[:k]

from collections import OrderedDict


class TTLCache:
    def __init__(self, capacity):
        if not isinstance(capacity, int) or isinstance(capacity, bool) or capacity < 1:
            raise ValueError("capacity must be an integer >= 1")
        self._cap = capacity
        self._data = OrderedDict()  # key -> (value, stored_time, ttl)
        self._hits = self._misses = self._evictions = self._expirations = 0

    def _purge(self, now):
        dead = [k for k, (_, t, ttl) in self._data.items()
                if ttl is not None and now >= t + ttl]
        for k in dead:
            del self._data[k]
            self._expirations += 1

    def put(self, key, value, now, ttl=None):
        if ttl is not None and ttl <= 0:
            raise ValueError("ttl must be positive")
        self._purge(now)
        if key in self._data:
            self._data[key] = (value, now, ttl)
            self._data.move_to_end(key)
            return
        if len(self._data) >= self._cap:
            self._data.popitem(last=False)
            self._evictions += 1
        self._data[key] = (value, now, ttl)

    def get(self, key, now):
        self._purge(now)
        if key in self._data:
            self._hits += 1
            self._data.move_to_end(key)
            return self._data[key][0]
        self._misses += 1
        return None

    def stats(self):
        return {"hits": self._hits, "misses": self._misses,
                "evictions": self._evictions, "expirations": self._expirations}

    def __len__(self):
        return len(self._data)

class Leaderboard:
    def __init__(self):
        self._best = {}
        self._stamp = {}
        self._tick = 0

    def submit(self, player, score):
        self._tick += 1
        cur = self._best.get(player)
        if cur is None or score > cur:
            self._best[player] = score
            self._stamp[player] = self._tick
            return True
        return False

    def best(self, player):
        if player not in self._best:
            raise KeyError(player)
        return self._best[player]

    def rank(self, player):
        b = self.best(player)
        return 1 + sum(1 for s in self._best.values() if s > b)

    def top(self, k):
        if k < 0:
            raise ValueError("k must be >= 0")
        order = sorted(self._best.items(),
                       key=lambda kv: (-kv[1], self._stamp[kv[0]]))
        return order[:k]

    def player_count(self):
        return len(self._best)

class MergeLedger:
    def __init__(self):
        self._root = {}      # element -> its component's root label
        self._members = {}   # root -> list of member elements
        self._value = {}     # element -> own value
        self._history = []   # (child_root, parent_root, n_moved)

    def add(self, x, value=0):
        if x in self._root:
            raise ValueError(f"element exists: {x!r}")
        self._root[x] = x
        self._members[x] = [x]
        self._value[x] = value

    def _r(self, x):
        if x not in self._root:
            raise KeyError(x)
        return self._root[x]

    def merge(self, a, b):
        ra, rb = self._r(a), self._r(b)
        if ra == rb:
            return False
        if len(self._members[ra]) < len(self._members[rb]):
            ra, rb = rb, ra          # ra keeps the bigger member list
        moved = self._members.pop(rb)
        for e in moved:
            self._root[e] = ra
        self._members[ra].extend(moved)
        self._history.append((rb, ra, len(moved)))
        return True

    def undo(self):
        if not self._history:
            raise RuntimeError("no merge to undo")
        child, parent, k = self._history.pop()
        mem = self._members[parent]
        tail = mem[len(mem) - k:]
        del mem[len(mem) - k:]
        self._members[child] = tail
        for e in tail:
            self._root[e] = child

    def same(self, a, b):
        return self._r(a) == self._r(b)

    def component_size(self, x):
        return len(self._members[self._r(x)])

    def component_value(self, x):
        return sum(self._value[e] for e in self._members[self._r(x)])

    def add_value(self, x, delta):
        if x not in self._root:
            raise KeyError(x)
        self._value[x] += delta

    def components(self):
        return len(self._members)

class IntervalSet:
    def __init__(self):
        self._iv = []  # sorted, disjoint, non-adjacent [lo, hi) pairs

    @staticmethod
    def _check(lo, hi):
        if lo >= hi:
            raise ValueError("require lo < hi")

    def add(self, lo, hi):
        self._check(lo, hi)
        merged = []
        for a, b in self._iv:
            if b < lo or a > hi:      # strictly apart (touching merges)
                merged.append((a, b))
            else:
                lo = min(lo, a)
                hi = max(hi, b)
        merged.append((lo, hi))
        merged.sort()
        self._iv = merged

    def remove(self, lo, hi):
        self._check(lo, hi)
        out = []
        for a, b in self._iv:
            if b <= lo or a >= hi:
                out.append((a, b))
            else:
                if a < lo:
                    out.append((a, lo))
                if b > hi:
                    out.append((hi, b))
        self._iv = out

    def contains(self, x):
        return any(a <= x < b for a, b in self._iv)

    def total(self):
        return sum(b - a for a, b in self._iv)

    def intervals(self):
        return list(self._iv)

    def gaps(self, lo, hi):
        self._check(lo, hi)
        res = []
        cur = lo
        for a, b in self._iv:
            if b <= lo or a >= hi:
                continue
            if a > cur:
                res.append((cur, a))
            cur = max(cur, b)
            if cur >= hi:
                break
        if cur < hi:
            res.append((cur, hi))
        return res

import heapq
import itertools


class TaskScheduler:
    def __init__(self):
        self._heap = []            # (-priority, seq, task_id)
        self._active = {}          # task_id -> (priority, seq)
        self._counter = itertools.count()

    def submit(self, task_id, priority):
        if task_id in self._active:
            raise ValueError(f"task already active: {task_id!r}")
        seq = next(self._counter)
        self._active[task_id] = (priority, seq)
        heapq.heappush(self._heap, (-priority, seq, task_id))

    def reprioritize(self, task_id, priority):
        if task_id not in self._active:
            raise KeyError(task_id)
        _, seq = self._active[task_id]
        self._active[task_id] = (priority, seq)
        heapq.heappush(self._heap, (-priority, seq, task_id))

    def cancel(self, task_id):
        if task_id not in self._active:
            raise KeyError(task_id)
        del self._active[task_id]

    def _settle(self):
        while self._heap:
            neg, seq, tid = self._heap[0]
            if self._active.get(tid) == (-neg, seq):
                return
            heapq.heappop(self._heap)

    def peek(self):
        self._settle()
        if not self._heap:
            raise IndexError("empty scheduler")
        return self._heap[0][2]

    def pop(self):
        self._settle()
        if not self._heap:
            raise IndexError("empty scheduler")
        _, _, tid = heapq.heappop(self._heap)
        del self._active[tid]
        return tid

    def priority_of(self, task_id):
        if task_id not in self._active:
            raise KeyError(task_id)
        return self._active[task_id][0]

    def __len__(self):
        return len(self._active)

class UndoStack:
    def __init__(self):
        self._items = []
        self._history = []  # ("push", value) or ("pop", value)

    def push(self, x):
        self._items.append(x)
        self._history.append(("push", x))

    def pop(self):
        if not self._items:
            raise IndexError("pop from empty UndoStack")
        v = self._items.pop()
        self._history.append(("pop", v))
        return v

    def peek(self):
        if not self._items:
            raise IndexError("peek from empty UndoStack")
        return self._items[-1]

    def undo(self):
        if not self._history:
            raise RuntimeError("nothing to undo")
        op, v = self._history.pop()
        if op == "push":
            self._items.pop()
        else:
            self._items.append(v)

    def __len__(self):
        return len(self._items)

class VersionedKV:
    def __init__(self):
        self._cur = {}
        self._snaps = [{}]  # index = version; version 0 is the empty state

    def set(self, key, value):
        self._cur[key] = value

    def delete(self, key):
        if key not in self._cur:
            raise KeyError(key)
        del self._cur[key]

    def get(self, key):
        if key not in self._cur:
            raise KeyError(key)
        return self._cur[key]

    def has(self, key):
        return key in self._cur

    def commit(self):
        self._snaps.append(dict(self._cur))
        return len(self._snaps) - 1

    def get_at(self, key, version):
        if not isinstance(version, int) or version < 1 or version > self.latest():
            raise ValueError(f"invalid version: {version!r}")
        snap = self._snaps[version]
        if key not in snap:
            raise KeyError(key)
        return snap[key]

    def rollback(self, version):
        if not isinstance(version, int) or version < 0 or version > self.latest():
            raise ValueError(f"invalid version: {version!r}")
        self._cur = dict(self._snaps[version])

    def latest(self):
        return len(self._snaps) - 1

import math


def rank_scores(scores):
    for s in scores:
        if isinstance(s, float) and math.isnan(s):
            raise ValueError("NaN score is not rankable")
    return [1 + sum(1 for t in scores if t > s) for s in scores]

import unicodedata


def truncate_display(s, width):
    if width < 0:
        raise ValueError("width must be >= 0")
    units = []
    for ch in s:
        if units and unicodedata.category(ch) in ("Mn", "Mc", "Me"):
            units[-1] += ch
        else:
            units.append(ch)
    return "".join(units[:width])

def kth_root_floor(n, k):
    if n < 0 or k < 1:
        raise ValueError("require n >= 0 and k >= 1")
    if k == 1 or n < 2:
        return n
    hi = 1
    while hi ** k <= n:
        hi <<= 1
    lo = hi >> 1
    while lo + 1 < hi:
        mid = (lo + hi) // 2
        if mid ** k <= n:
            lo = mid
        else:
            hi = mid
    return lo

import math


def allocate_shares(total, weights):
    if total < 0:
        raise ValueError("total must be >= 0")
    if not weights:
        raise ValueError("weights must be non-empty")
    for w in weights:
        if w < 0:
            raise ValueError("negative weight")
    wsum = sum(weights)
    if wsum == 0:
        raise ValueError("sum of weights must be > 0")
    quotas = [total * w / wsum for w in weights]
    shares = [math.floor(q) for q in quotas]
    leftover = total - sum(shares)
    order = sorted(range(len(weights)),
                   key=lambda i: (-(quotas[i] - shares[i]), i))
    for i in order[:leftover]:
        shares[i] += 1
    return shares

def round_robin(iterables):
    def gen():
        active = [iter(it) for it in iterables]
        while active:
            still = []
            for it in active:
                try:
                    val = next(it)
                except StopIteration:
                    continue
                still.append(it)
                yield val
            active = still
    return gen()

def weighted_median(values, weights):
    if len(values) != len(weights):
        raise ValueError("values and weights must have the same length")
    if not values:
        raise ValueError("empty dataset")
    for w in weights:
        if w < 0:
            raise ValueError("negative weight")
    total = sum(weights)
    if total <= 0:
        raise ValueError("total weight must be > 0")
    pairs = sorted(zip(values, weights), key=lambda p: p[0])
    threshold = total / 2 - 1e-9
    cum = 0.0
    for v, w in pairs:
        cum += w
        if cum >= threshold:
            return v
    return pairs[-1][0]

import math


def vector_norm(v):
    scale = 0.0
    for x in v:
        if not math.isfinite(x):
            raise ValueError("non-finite entry")
        scale = max(scale, abs(x))
    if scale == 0.0:
        return 0.0
    ssq = math.fsum((x / scale) ** 2 for x in v)
    return scale * math.sqrt(ssq)

import heapq


def max_bounty(jobs, cap):
    if cap < 1:
        raise ValueError("cap must be >= 1")
    heap = []
    for d, p in sorted(jobs):
        heapq.heappush(heap, p)
        if len(heap) > d * cap:
            heapq.heappop(heap)
    return sum(heap)

def longest_echo(s):
    n = len(s)
    if n < 2:
        return 0
    MOD = (1 << 61) - 1
    B = 131
    H = [0] * (n + 1)
    for i in range(n):
        H[i + 1] = (H[i] * B + ord(s[i])) % MOD
    P = [1] * (n + 1)
    for i in range(n):
        P[i + 1] = P[i] * B % MOD

    def has_dup(L):
        seen = set()
        add = seen.add
        pl = P[L]
        for i in range(n - L + 1):
            h = (H[i + L] - H[i] * pl) % MOD
            if h in seen:
                return True
            add(h)
        return False

    lo, hi = 1, n - 1
    best = 0
    while lo <= hi:
        mid = (lo + hi) // 2
        if has_dup(mid):
            best = mid
            lo = mid + 1
        else:
            hi = mid - 1
    return best

from collections import Counter


def count_locked_pairs(values, m):
    if m < 1:
        raise ValueError("m must be >= 1")
    buckets = Counter((v % m, v % 2) for v in values)
    total = 0
    for (r, p), c in buckets.items():
        rc = (m - r) % m
        if rc == r:
            total += c * (c - 1) // 2
        elif rc > r:
            total += c * buckets.get((rc, p), 0)
    return total

def peak_load(intervals):
    events = []
    for s, e in intervals:
        events.append((s, 1))
        events.append((e, -1))
    events.sort()
    best = 0
    best_t = 0
    cur = 0
    i = 0
    n = len(events)
    while i < n:
        t = events[i][0]
        while i < n and events[i][0] == t:
            cur += events[i][1]
            i += 1
        if cur > best:
            best = cur
            best_t = t
    return (best, best_t)

from collections import deque


def count_stable_windows(readings, tol):
    n = len(readings)
    maxd = deque()
    mind = deque()
    total = 0
    left = 0
    for right in range(n):
        x = readings[right]
        while maxd and readings[maxd[-1]] <= x:
            maxd.pop()
        maxd.append(right)
        while mind and readings[mind[-1]] >= x:
            mind.pop()
        mind.append(right)
        while readings[maxd[0]] - readings[mind[0]] > tol:
            if maxd[0] == left:
                maxd.popleft()
            if mind[0] == left:
                mind.popleft()
            left += 1
        total += right - left + 1
    return total

def summarize_by_category(rows):
    if not isinstance(rows, list):
        raise TypeError("rows must be a list")
    result = {}
    for i, row in enumerate(rows):
        if not isinstance(row, tuple) or len(row) != 3:
            raise TypeError("row %d must be a 3-tuple" % i)
        category, amount, refunded = row
        if not isinstance(category, str) or category == "":
            raise ValueError("row %d has an invalid category" % i)
        if isinstance(amount, bool) or not isinstance(amount, (int, float)):
            raise TypeError("row %d has a non-numeric amount" % i)
        if amount < 0:
            raise ValueError("row %d has a negative amount" % i)
        if not isinstance(refunded, bool):
            raise TypeError("row %d has a non-bool refunded flag" % i)
        bucket = result.get(category)
        if bucket is None:
            bucket = {"count": 0, "gross": 0.0, "net": 0.0, "largest": 0.0}
            result[category] = bucket
        bucket["count"] += 1
        bucket["gross"] += float(amount)
        if not refunded:
            bucket["net"] += float(amount)
        if float(amount) > bucket["largest"]:
            bucket["largest"] = float(amount)
    return result

def clamp_values(values, low, high):
    if not isinstance(values, list):
        raise TypeError("values must be a list")
    for b in (low, high):
        if isinstance(b, bool) or not isinstance(b, (int, float)):
            raise TypeError("bounds must be numbers")
    if low > high:
        raise ValueError("low must not exceed high")
    out = []
    for i, v in enumerate(values):
        if isinstance(v, bool) or not isinstance(v, (int, float)):
            raise TypeError("element at index %d is not a number" % i)
        if v < low:
            out.append(low)
        elif v > high:
            out.append(high)
        else:
            out.append(v)
    return out

def flatten_depth(nested, max_depth):
    if not isinstance(nested, list):
        raise TypeError("nested must be a list")
    if isinstance(max_depth, bool) or not isinstance(max_depth, int):
        raise TypeError("max_depth must be an int")
    if max_depth < 0:
        raise ValueError("max_depth must be >= 0")
    out = []
    stack = [(nested, 0)]
    while stack:
        current, depth = stack.pop()
        if isinstance(current, list) and depth <= max_depth:
            for item in reversed(current):
                stack.append((item, depth + 1))
        else:
            out.append(current)
    return out

def parse_duration(text):
    if not isinstance(text, str):
        raise TypeError("expected str, got " + type(text).__name__)
    if text.strip() == "":
        raise ValueError("empty duration")
    units = {"h": 3600, "m": 60, "s": 1}
    order = "hms"
    digits = "0123456789"
    i = 0
    total = 0
    next_allowed = 0
    n = len(text)
    while i < n:
        j = i
        while j < n and text[j] in digits:
            j += 1
        if j == i or j >= n or text[j] not in units:
            raise ValueError("malformed duration: " + text)
        unit = text[j]
        idx = order.index(unit)
        if idx < next_allowed:
            raise ValueError("malformed duration: " + text)
        next_allowed = idx + 1
        total += int(text[i:j]) * units[unit]
        i = j + 1
    return total

def render_template(template, context):
    if not isinstance(template, str):
        raise TypeError("template must be a string")
    if not isinstance(context, dict):
        raise TypeError("context must be a dict")
    allowed = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789_"
    out = []
    i = 0
    n = len(template)
    while i < n:
        ch = template[i]
        if ch == "{":
            if i + 1 < n and template[i + 1] == "{":
                out.append("{")
                i += 2
                continue
            start = i
            j = i + 1
            while j < n and template[j] in allowed:
                j += 1
            if j >= n:
                raise ValueError("unclosed placeholder at position %d" % start)
            if template[j] != "}":
                raise ValueError("invalid placeholder at position %d" % start)
            if j == start + 1:
                raise ValueError("empty placeholder at position %d" % start)
            name = template[start + 1:j]
            if name not in context:
                raise KeyError(name)
            out.append(str(context[name]))
            i = j + 1
        elif ch == "}":
            if i + 1 < n and template[i + 1] == "}":
                out.append("}")
                i += 2
            else:
                raise ValueError("stray '}' at position %d" % i)
        else:
            out.append(ch)
            i += 1
    return "".join(out)

def eval_rpn(tokens):
    if not isinstance(tokens, list):
        raise TypeError("tokens must be a list")
    if len(tokens) == 0:
        raise ValueError("empty expression")
    stack = []
    for i, tok in enumerate(tokens):
        if not isinstance(tok, str):
            raise TypeError("token %d must be a string" % i)
        if tok in ("+", "-", "*", "/"):
            if len(stack) < 2:
                raise ValueError("stack underflow at token %d" % i)
            right = stack.pop()
            left = stack.pop()
            if tok == "+":
                stack.append(left + right)
            elif tok == "-":
                stack.append(left - right)
            elif tok == "*":
                stack.append(left * right)
            else:
                if right == 0:
                    raise ZeroDivisionError("division by zero at token %d" % i)
                neg = (left < 0) != (right < 0)
                q = abs(left) // abs(right)
                stack.append(-q if neg else q)
        else:
            body = tok[1:] if tok[:1] in ("+", "-") else tok
            if body == "" or body.strip("0123456789") != "":
                raise ValueError("unknown token %r at token %d" % (tok, i))
            stack.append(int(tok))
    if len(stack) != 1:
        raise ValueError("leftover operands")
    return stack[0]

def deep_get(data, path):
    if not isinstance(path, str):
        raise TypeError("path must be a string")
    if path == "":
        raise ValueError("path must not be empty")
    segments = path.split(".")
    if "" in segments:
        raise ValueError("empty segment in path")

    def walk(node, segs):
        if not segs:
            return node
        seg = segs[0]
        rest = segs[1:]
        if isinstance(node, dict):
            if seg not in node:
                raise KeyError(seg)
            return walk(node[seg], rest)
        if isinstance(node, list):
            stripped = seg[1:] if seg[:1] == "-" else seg
            if stripped == "" or stripped.strip("0123456789") != "":
                raise ValueError("invalid index: " + seg)
            idx = int(seg)
            if idx >= len(node) or idx < -len(node):
                raise IndexError("index out of range: " + seg)
            return walk(node[idx], rest)
        raise TypeError("cannot descend into " + type(node).__name__ + " at segment " + seg)

    return walk(data, segments)

def top_k_frequent(items, k):
    if not isinstance(items, list):
        raise TypeError("items must be a list")
    if isinstance(k, bool) or not isinstance(k, int):
        raise TypeError("k must be an int")
    if k < 0:
        raise ValueError("k must be >= 0")
    counts = {}
    first_seen = {}
    for pos, v in enumerate(items):
        if v in counts:
            counts[v] += 1
        else:
            counts[v] = 1
            first_seen[v] = pos
    remaining = list(counts.keys())
    out = []
    while remaining and len(out) < k:
        best = 0
        for i in range(1, len(remaining)):
            a, b = remaining[i], remaining[best]
            if counts[a] > counts[b] or (counts[a] == counts[b] and first_seen[a] < first_seen[b]):
                best = i
        chosen = remaining.pop(best)
        out.append((chosen, counts[chosen]))
    return out
